using LigaVolley.Application.MatchSheets;namespace LigaVolley.Api.Endpoints.Scorer;
internal static class ScorerOfflineSyncEndpoints{public static IEndpointRouteBuilder MapScorerOfflineSyncEndpoints(this IEndpointRouteBuilder endpoints){var group=endpoints.MapGroup("/api/scorer/matches/{matchId:int}").WithTags("Scorer Offline Sync");
// Example: POST /api/scorer/matches/123/sync
// Body: { "sheetUuid": "79507046-47df-44ac-81a5-bd69e4014492", "sessionUuid": "961a6677-f69f-4e8f-a92e-065ec2c97117", "deviceId": "tablet-cancha-01", "events": [{ "eventUuid": "890d92bf-844b-44e3-8de6-ce65bbadfa33", "sequence": 1, "type": "PREPARE_SET", "occurredAt": "2026-08-25T20:31:04Z", "payload": {} }] }
group.MapPost("/sync",async(int matchId,SyncMatchSheetRequest request,OfflineSyncService service,CancellationToken ct)=>Results.Ok(await service.SyncAsync(matchId,request,ct))).WithSummary("Synchronize an atomic ordered batch of offline scorer events").WithDescription("Retries use EventUuid; new events are contiguous per session and execute through the online MatchEngine. When a sporting failure is attributable to one event, ProblemDetails includes eventUuid and localSequence.").Produces<SyncMatchSheetResponse>().ProducesProblem(400).ProducesProblem(404).ProducesProblem(409);
// Example: POST /api/scorer/matches/123/take-over
// Body: { "sheetUuid": "79507046-47df-44ac-81a5-bd69e4014492", "expectedSessionUuid": "961a6677-f69f-4e8f-a92e-065ec2c97117", "deviceId": "tablet-cancha-02", "clientRequestId": "02cbd7a0-3990-4ee8-869a-c48510336321" }
group.MapPost("/take-over",async(int matchId,TakeOverMatchSheetRequest request,OfflineSyncService service,CancellationToken ct)=>Results.Ok(await service.TakeOverAsync(matchId,request,ct))).WithSummary("Take over an operational MatchSheet").WithDescription("Abandons the expected active session, creates one active session at sequence zero, and preserves sporting state.").Produces<TakeOverMatchSheetResponse>().ProducesProblem(400).ProducesProblem(404).ProducesProblem(409);return endpoints;}}
